import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1024, height: 768 } })
const failures = []
page.on('pageerror', e => failures.push(e.message))
try {
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.evaluate(() => localStorage.clear())
  await page.reload({ waitUntil: 'load' })
  await page.getByText('Single Player').click()
  await page.locator('#charName').fill('Rowan')
  await page.getByText('Create character').click()
  if (await page.locator('.worldChoice').count() !== 20) throw new Error('Expected 20 seeded worlds')
  await page.locator('.worldChoice').nth(0).click()
  await page.locator('#enterWorld').click()
  await page.waitForSelector('#hud:not(.hide)')
  await page.keyboard.press('Digit2')
  await page.mouse.click(300, 440)
  await page.waitForTimeout(300)
  const afterMining = await page.evaluate(() => JSON.parse(localStorage.getItem('laveria-save')))
  const inventory = JSON.stringify(afterMining.character.inventory)
  await page.keyboard.press('Escape')
  await page.locator('#toWorlds').click()
  await page.locator('.worldChoice').nth(1).click()
  await page.locator('#enterWorld').click()
  await page.waitForSelector('#hud:not(.hide)')
  const afterSwitch = await page.evaluate(() => JSON.parse(localStorage.getItem('laveria-save')))
  if (JSON.stringify(afterSwitch.character.inventory) !== inventory) throw new Error('Inventory did not persist across worlds')
  if (!afterSwitch.worlds['18427'] || !afterSwitch.worlds['73109']) throw new Error('World records missing after switching')
  if (failures.length) throw new Error(`Browser errors: ${failures.join('; ')}`)
  console.log('Smoke test passed: character creation, 20 worlds, world switching, inventory persistence; no page errors.')
} finally { await browser.close() }
